    subtopic: "Quantitative Aptitude",
    question: "The simple and compound interest that can be earned in two years at the same rate is Rs 1,800 and Rs 1,881 respectively. What is the rate (percent per annum) of interest?",
    options: ["10", "11", "9", "8"],
    answer: "9",
    explanation: "CI − SI for 2 years = P(r/100)² = 81; also SI = 2P(r/100) = 1800 ⇒ P(r/100)=900. Thus r/100 = 81/900 = 0.09 ⇒ r = 9%."
