  subtopic: "Mathematics",
  question: "If a3 + b3 = 28 and ab = 3, then what is the value of a + b?",
  options: [
    "2",
    "4",
    "9",
    "3"
  ],
  answer: "4",
  explanation: "(a+b)^3 = a^3+b^3+3ab(a+b). Let s = a+b: s^3 = 28 + 3*3*s = 28 + 9s. s^3 - 9s - 28 = 0. s = 4: 64 - 36 - 28 = 0. So a+b = 4."
