  subtopic: "Mathematics",
  question: "Thrice a fraction is greater than its reciprocal by 46/7. What is the fraction?",
  options: [
    "7/3",
    "3/7",
    "5/4",
    "4/5"
  ],
  answer: "7/3",
  explanation: "Let fraction be x. 3x = 1/x + 46/7 => 3x - 1/x = 46/7. Multiply by 7x: 21x^2 - 7 = 46x => 21x^2 - 46x - 7 = 0. Solve: x = (46 ± sqrt(2116+588))/42 = (46 ± sqrt(2704))/42 = (46 ± 52)/42. Positive: 98/42 = 7/3."
